exercise.solution:
def place_restante(budget, systeme, demande, reserve):
    if min(budget,systeme,demande,reserve)<0:raise ValueError('budget négatif')
    reste=budget-systeme-demande-reserve
    if reste<0:raise ValueError('contexte insuffisant')
    return reste

exercise.check:
assert place_restante(1000,200,300,100)==400
assert place_restante(10,2,3,5)==0
try:place_restante(9,2,3,5)
except ValueError:pass
else:raise AssertionError('dépassement accepté')
